INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('4dde23db55e2a5b3', 'brand_speedin', 'Hair Skin & Nails', 'Any video for the Hair Skin & Nails strips: hair, skin, nails, the daily routine.', 'sparkles', '<path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"/><path d="M20 2v4"/><path d="M22 4h-4"/><circle cx="4" cy="20" r="2"/>', '#BE185D', 1, 0, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('b9241e7f152cb1fb', 'brand_speedin', '5b0bde9e8509bdf9', 1, 1, 1, 'live', 'Strip on the tongue in the car', 'The strip going on the tongue in the first second shows the whole product before anyone can scroll.', 'Anyone who drives to work, the gym or school pickup', 'Energy', 'Car selfie, show and tell', '["This little strip replaced my morning energy drink.", "Watch this. No water, no can, nothing.", "I used to buy one of these every single morning."]', '[{"label": "Open · 0 to 3s", "text": "Strip up to the lens, then onto your tongue. Say the first line."}, {"label": "Middle", "text": "Tongue out so we see it melting. Open the pack and show how many are inside. Hold up an old can or cup (no logo facing camera) and say what you used to spend time and sugar on."}, {"label": "Close", "text": "Pack next to your face. Say how your drive or morning felt, in your own words."}]', 'A strip held between two fingers right in front of the lens, then straight onto the tongue', 'Tongue out on camera with the strip half melted, then the can comes out next to the pack', '[{"brand": "NuStrips", "what": "Sit in your parked car, hold a Speedin Energy strip up to the camera, put it on your tongue and show it melting. Then hold up the energy drink can you used to buy and say why you stopped.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('2bb5c82659b168f1', 'brand_speedin', 'b9241e7f152cb1fb', 'upload', 'amb/brand_speedin/inspo-nustrips-car-can.mp4', 'NuStrips (inspiration)', 'Sit in your parked car, hold a Speedin Energy strip up to the camera, put it on your tongue and show it melting. Then hold up the energy drink can you used to buy and say why you stopped.', '5b0bde9e8509bdf9', 1, 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('060b976824fd041c', 'brand_speedin', '5b0bde9e8509bdf9', 1, 2, 2, 'live', 'It is 2:56pm and I know exactly what happens next', 'Everyone knows the 3pm slump, so the clock alone makes people stop.', 'Office workers, work from home parents, students', 'Energy', 'Desk POV, 3pm slump', '["It is 2:56 and I already know how this goes.", "This is the exact moment my day falls apart.", "My 3pm used to mean a second coffee. Not anymore."]', '[{"label": "Open · 0 to 3s", "text": "Over the shoulder at your desk, then turn the laptop so we see the time."}, {"label": "Middle", "text": "Walk toward the coffee maker, stop, come back. Open a strip and put it on your tongue. Say it melts in about 30 seconds, no water."}, {"label": "Close", "text": "Back to typing, or out the door to the next thing. Say what your afternoon feels like now."}]', 'Laptop clock reading 2:56 PM, you looking tired at it', 'You walk to the coffee maker, stop, and turn back to the strip', '[{"brand": "The Patch Remedy", "what": "Film yourself at your desk right before 3pm, point at the clock on your laptop or phone, skip the coffee run and put a Speedin Energy strip on your tongue instead. Then get back to work.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('233640164c53cca8', 'brand_speedin', '060b976824fd041c', 'upload', 'amb/brand_speedin/inspo-patchremedy-3pm-desk.mp4', 'The Patch Remedy (inspiration)', 'Film yourself at your desk right before 3pm, point at the clock on your laptop or phone, skip the coffee run and put a Speedin Energy strip on your tongue instead. Then get back to work.', '5b0bde9e8509bdf9', 1, 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('3743be8df25463ff', 'brand_speedin', '65c17bef036d1527', 1, 3, 3, 'live', 'If you are like me, your brain starts at night', 'A real messy night routine feels like the viewer''s own house.', 'Moms, busy parents, anyone whose mind races at night', 'Sleep', 'Night routine, voiceover', '["If you are like me, your brain turns on the second the kids are asleep.", "My night routine, the real one.", "I used to lie there for an hour. Here is what changed."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom, brushing teeth, first line on screen."}, {"label": "Middle", "text": "Quick clips: kitchen, folding something, couch. Open a Sleep strip and put it on your tongue, say no water and no pills."}, {"label": "Close", "text": "Lights off, you walking to bed. Say how you feel when you wake up, in your words."}]', 'You in the bathroom mirror, toothbrush in mouth, tired face', 'The lights go off and the strip goes on in the dark kitchen or bedroom', '[{"brand": "Winks", "what": "Film your real night routine: brushing teeth, kitchen tidy, couch, then a Speedin Sleep strip on your tongue before lights out. Talk over it like you are telling a friend.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('7630a7bdf83366ff', 'brand_speedin', '3743be8df25463ff', 'upload', 'amb/brand_speedin/inspo-winks-night-routine.mp4', 'Winks (inspiration)', 'Film your real night routine: brushing teeth, kitchen tidy, couch, then a Speedin Sleep strip on your tongue before lights out. Talk over it like you are telling a friend.', '65c17bef036d1527', 1, 1, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('4a9cdf9775a360df', 'brand_speedin', '4dde23db55e2a5b3', 1, 4, 4, 'live', 'My man''s logic: healthy means a mess', 'The mess is funny and makes the strip look easy without saying it.', 'Couples, roommates, siblings', 'Hair Skin & Nails', 'Two person skit', '["My man''s logic: healthy means scoops, spills and cleaning the whole kitchen.", "Every morning I watch this happen.", "He thinks this is the healthy way."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot from the counter, partner mid mess, text on screen."}, {"label": "Middle", "text": "Shaking the shaker, powder on the counter, pill bottles. You step in with the pack."}, {"label": "Close", "text": "Strip on the tongue, partner shrugs, you both walk off. Leave the mess in frame."}]', 'Partner spilling powder everywhere, you watching with a mug, text on top', 'The hand off: you peel a strip and stick it on their tongue', '[{"brand": "Grüns", "what": "Two people, one kitchen. Your partner makes a huge mess with scoops, shakers and pill bottles while you sip your coffee and watch. Then you hand them a Speedin strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8a744e0f1a0578df', 'brand_speedin', '4a9cdf9775a360df', 'upload', 'amb/brand_speedin/inspo-gruns-couple-skit.mp4', 'Grüns (inspiration)', 'Two people, one kitchen. Your partner makes a huge mess with scoops, shakers and pill bottles while you sip your coffee and watch. Then you hand them a Speedin strip.', '4dde23db55e2a5b3', 1, 1, 4);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('ba1077bf3529c265', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 5, 'live', 'Feeling lazy? A day with the strip', 'Fast cuts of a real life show where the strip fits without a single word of selling.', 'Busy, active creators who can film 5 places in one day', 'Energy', 'Day in my life montage', '["Feeling lazy? Same. Here is my fix.", "Every place this strip came with me today.", "My whole day runs on one tiny strip."]', '[{"label": "Open · 0 to 3s", "text": "Close up of your hands opening the pouch, text on screen."}, {"label": "Middle", "text": "4 or 5 two second clips: car, kitchen, closet, gym, pack in your bag. Strip on the tongue in at least one."}, {"label": "Close", "text": "Pack in your bag or drawer, text: Perform. Recover. Glow."}]', 'Hands peeling the pouch open with text: Feeling lazy?', 'Strip goes on the tongue in the car, then a quick cut to you moving at the gym', '[{"brand": "NuStrips", "what": "Film quick clips of your real day: opening a Speedin Energy strip, putting it on in the car, the gym, getting dressed, the pack in your bag. Short clips, one line of text on each.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('38f577727a7101ea', 'brand_speedin', 'ba1077bf3529c265', 'upload', 'amb/brand_speedin/inspo-nustrips-day-montage.mp4', 'NuStrips (inspiration)', 'Film quick clips of your real day: opening a Speedin Energy strip, putting it on in the car, the gym, getting dressed, the pack in your bag. Short clips, one line of text on each.', '5b0bde9e8509bdf9', 1, 1, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('da2f5b8fc9564794', 'brand_speedin', '65c17bef036d1527', 0, 0, 6, 'live', 'Night shift hack unlocked', 'Night shift workers instantly see themselves, and the uniform tells the story.', 'Nurses, shift workers, first responders', 'Sleep', 'Shift worker tip', '["Night shift people, this one is for you.", "Trying to sleep at 10am is a nightmare.", "I wish I had this when I started nights."]', '[{"label": "Open · 0 to 3s", "text": "Scrubs on, bedroom, first line with text on screen."}, {"label": "Middle", "text": "Talk about bright daylight and noise. Close the curtains, open a strip, put it on."}, {"label": "Close", "text": "Get into bed. Say how you feel when you wake up for your next shift."}]', 'You in scrubs pointing at the camera, text: Night shift hack unlocked', 'You close the blackout curtains and the strip goes on', '[{"brand": "Manta Sleep", "what": "In your scrubs or work uniform after a night shift, tell us how hard it is to sleep at 10am when the world is awake, then put a Speedin Sleep strip on before you get into bed.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('39a670f8b3ecfdb7', 'brand_speedin', 'da2f5b8fc9564794', 'upload', 'amb/brand_speedin/inspo-manta-night-nurse.mp4', 'Manta Sleep (inspiration)', 'In your scrubs or work uniform after a night shift, tell us how hard it is to sleep at 10am when the world is awake, then put a Speedin Sleep strip on before you get into bed.', '65c17bef036d1527', 1, 1, 6);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f90f8e1a4df53d01', 'brand_speedin', '4dde23db55e2a5b3', 0, 0, 7, 'live', 'My hairstylist noticed before I did', 'Someone else noticing is more believable than you saying it.', 'Women who get regular cuts or color', 'Hair Skin & Nails', 'Stylist reaction, then talking head', '["My hairstylist asked me what I changed.", "When your stylist points it out, you know.", "I did not notice until she said it."]', '[{"label": "Open · 0 to 3s", "text": "Salon chair mirror selfie, stylist pointing at your hair."}, {"label": "Middle", "text": "At home, pack in hand. Say you take one Lemon strip every morning, no pills to swallow."}, {"label": "Close", "text": "Back to the salon clip or a hair flip. Say results are different for everyone and this is just you."}]', 'Salon mirror selfie, stylist holding up a section of your hair', 'Back home, you hold up the pack and say what you changed', '[{"brand": "MaryRuth''s", "what": "Film a mirror clip at the salon (or ask your stylist to point at your hair), then cut to you at home holding the Speedin Hair Skin & Nails pack and talking about taking it every day.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('24c6e3560b542b24', 'brand_speedin', 'f90f8e1a4df53d01', 'upload', 'amb/brand_speedin/inspo-maryruth-stylist-growth.mp4', 'MaryRuth''s (inspiration)', 'Film a mirror clip at the salon (or ask your stylist to point at your hair), then cut to you at home holding the Speedin Hair Skin & Nails pack and talking about taking it every day.', '4dde23db55e2a5b3', 1, 1, 7);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f406de43b2fc59ca', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 8, 'live', 'Trying it for the first time on camera', 'A real first reaction feels honest because it is.', 'Anyone, works best for creators who talk to camera easily', 'Energy', 'Unboxing and first try', '["Okay, these came today and I have no idea what to expect.", "Energy in a strip? Let''s see.", "First time trying this, you are watching it live."]', '[{"label": "Open · 0 to 3s", "text": "Hold the package up and say the first line."}, {"label": "Middle", "text": "Open the box, read the back out loud, peel a strip, put it on your tongue and show it."}, {"label": "Close", "text": "Honest verdict on taste and how long it took to melt. Hold the pack up."}]', 'You holding the mailer bag or box up to the camera, surprised face', 'Tongue out showing the strip, then your reaction to the Strawberry Mint taste', '[{"brand": "NuStrips", "what": "Open your Speedin pack on camera, read what is inside, put your first Energy strip on your tongue and give your honest first reaction to the taste and the melt.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('206f69d5388c070f', 'brand_speedin', 'f406de43b2fc59ca', 'upload', 'amb/brand_speedin/inspo-nustrips-first-try.mp4', 'NuStrips (inspiration)', 'Open your Speedin pack on camera, read what is inside, put your first Energy strip on your tongue and give your honest first reaction to the taste and the melt.', '5b0bde9e8509bdf9', 1, 1, 8);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('37a0ae4d8c2bfec6', 'brand_speedin', '65c17bef036d1527', 0, 0, 9, 'live', 'Try this before bed if your mind will not stop', 'A simple routine is easy to copy, so people save it.', 'Women 40 plus, readers, anyone with a racing mind at night', 'Sleep', 'Bedtime routine tip', '["If your mind will not shut off at night, try this.", "Work, random conversations, tomorrow''s to do list. Sound familiar?", "Here is my whole wind down. It takes ten minutes."]', '[{"label": "Open · 0 to 3s", "text": "Sitting up in bed, first line, soft lamp light."}, {"label": "Middle", "text": "Show the Sleep pack, put a strip on, put your phone face down, open your book."}, {"label": "Close", "text": "Say this is the routine that works for you. Lamp off."}]', 'You sitting up in bed, robe on, talking low like it is late', 'The book comes out and the voice drops to a whisper', '[{"brand": "Budpop", "what": "Sit up in bed in your robe or pajamas and walk us through your wind down: Speedin Sleep strip, phone away, a few pages of a book. Calm voice, one take.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('1a6306b1cd42fad8', 'brand_speedin', '37a0ae4d8c2bfec6', 'upload', 'amb/brand_speedin/inspo-budpop-mind-wont-stop.mp4', 'Budpop (inspiration)', 'Sit up in bed in your robe or pajamas and walk us through your wind down: Speedin Sleep strip, phone away, a few pages of a book. Calm voice, one take.', '65c17bef036d1527', 1, 1, 9);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('b3efb2820bda4ee9', 'brand_speedin', '4dde23db55e2a5b3', 0, 0, 10, 'live', 'Look at my nails though', 'Nails held to the lens are proof you can see, no before and after needed.', 'Women 35 plus, anyone who has tried a lot of supplements', 'Hair Skin & Nails', 'Selfie testimonial', '["I did not think another supplement would impress me. But look at my nails.", "Two months in and this is the part I did not expect.", "Okay, I have to show you my nails."]', '[{"label": "Open · 0 to 3s", "text": "Kitchen selfie, nails right up to the lens."}, {"label": "Middle", "text": "Hold up the pack, peel a strip, put it on. Say it is one strip a day, no water."}, {"label": "Close", "text": "Hair and nails to camera one more time. Say what you have noticed, only your own experience."}]', 'Your hand coming up to the lens, nails first', 'You run your hand through your hair while talking', '[{"brand": "Obvi", "what": "Selfie in your kitchen. Say you did not expect another supplement to impress you, then hold your nails up to the camera and talk about your Speedin Hair Skin & Nails strips.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('7e813a2d09c816c4', 'brand_speedin', 'b3efb2820bda4ee9', 'upload', 'amb/brand_speedin/inspo-obvi-look-at-my-nails.mp4', 'Obvi (inspiration)', 'Selfie in your kitchen. Say you did not expect another supplement to impress you, then hold your nails up to the camera and talk about your Speedin Hair Skin & Nails strips.', '4dde23db55e2a5b3', 1, 1, 10);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('981c15fafed42a85', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 11, 'live', '5:30am alarm, new routine', 'The groan at the alarm is relatable before you say a single word.', 'Early shift workers, gym at dawn people, new jobs, parents', 'Energy', 'Early alarm storytime', '["5:30 is now a real time I get up. Who knew.", "Dark mornings, early alarms, new job.", "I am not a morning person. Here is how I fake it."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on the nightstand. Alarm, groan, hand over your face."}, {"label": "Middle", "text": "Sit up on the bed, talk about your new early schedule, put a strip on your tongue mid sentence."}, {"label": "Close", "text": "Coat on, keys, out the door into the dark."}]', 'You face down in a pillow, alarm going, hand over your face', 'The strip comes out of your pocket while you are still in pajamas', '[{"brand": "Ankhway", "what": "Start in bed with your alarm going off in the dark, then sit on the edge of the bed and talk about your early mornings while you put a Speedin Energy strip on. End walking out the door.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('b32e6b5566365b40', 'brand_speedin', '981c15fafed42a85', 'upload', 'amb/brand_speedin/inspo-ankhway-530am-alarm.mp4', 'Ankhway (inspiration)', 'Start in bed with your alarm going off in the dark, then sit on the edge of the bed and talk about your early mornings while you put a Speedin Energy strip on. End walking out the door.', '5b0bde9e8509bdf9', 1, 1, 11);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('02c89425fc79adcf', 'brand_speedin', '65c17bef036d1527', 0, 0, 12, 'live', 'Flying with my supplements, TSA edition', 'Travel is the moment pills and powders are most annoying, so the strip wins on sight.', 'Travelers, people who fly for work', 'Sleep', 'Airport vlog', '["Flying with supplements used to be a whole thing.", "Is this TSA friendly? Yep.", "My entire supplement routine fits in my pocket now."]', '[{"label": "Open · 0 to 3s", "text": "Pack sitting on the security bin, your hand grabbing it."}, {"label": "Middle", "text": "Walking to the gate selfie. Show how flat the pack is. Put a strip on, no water."}, {"label": "Close", "text": "In your seat or at the window. Pack in your hand, last line."}]', 'Your bag on the security belt with the Speedin pack on top', 'Strip on the tongue at the gate or in your seat', '[{"brand": "Pure Genius Protein", "what": "Film your trip through the airport: bag on the security belt, walking to the gate, strip out of your pocket. Talk about how strips mean no rattling bottles and no water needed on the plane.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('befee75ad20897ba', 'brand_speedin', '02c89425fc79adcf', 'upload', 'amb/brand_speedin/inspo-puregenius-airport-tsa.mp4', 'Pure Genius Protein (inspiration)', 'Film your trip through the airport: bag on the security belt, walking to the gate, strip out of your pocket. Talk about how strips mean no rattling bottles and no water needed on the plane.', '65c17bef036d1527', 1, 1, 12);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('ac1973ec3828ddd7', 'brand_speedin', '4dde23db55e2a5b3', 0, 0, 13, 'live', 'My hair routine, inside and out', 'The strip slides into a routine people already love watching.', 'Beauty and hair creators', 'Hair Skin & Nails', 'Hair routine GRWM', '["My hair routine this season.", "Outside steps, then the inside step most people skip.", "Everything I do for my hair, in order."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom mirror, hands in your hair, text on screen."}, {"label": "Middle", "text": "Quick clips of your real products, then towel on, strip on the tongue."}, {"label": "Close", "text": "Finished hair, hair flip, pack in hand."}]', 'Hands in your hair at the mirror, text: hair routine', 'Towel on your head, strip on your tongue', '[{"brand": "Hairburst", "what": "Film your hair routine in the bathroom: scalp, wash, towel. End with your Speedin Hair Skin & Nails strip as the inside step, then the finished hair.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('7f4ebb4fb3cf68ca', 'brand_speedin', 'ac1973ec3828ddd7', 'upload', 'amb/brand_speedin/inspo-hairburst-hair-routine.mp4', 'Hairburst (inspiration)', 'Film your hair routine in the bathroom: scalp, wash, towel. End with your Speedin Hair Skin & Nails strip as the inside step, then the finished hair.', '4dde23db55e2a5b3', 1, 1, 13);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('04417da083e43839', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 14, 'live', 'Two things that never leave my bag', 'The two things list makes people wait for the second item.', 'Gym goers, pickleball and golf players, coaches, runners', 'Energy', 'What''s in my bag', '["Two things that never leave my gym bag.", "I am at the court 5 days a week and these two always come with me.", "Thing one is obvious. Thing two is not."]', '[{"label": "Open · 0 to 3s", "text": "Phone low on the floor, you crouched over your bag holding your gear."}, {"label": "Middle", "text": "Put the gear down, pull out the Speedin pack, show a strip, put one on before you play."}, {"label": "Close", "text": "Toss the pack back in the bag and walk into your session."}]', 'Low angle, you holding your main piece of gear up to the lens', 'The second thing comes out and it is tiny', '[{"brand": "Infraredi", "what": "Crouch next to your gym bag, sports bag or work bag and say: two things that never leave my bag. Pull out your gear, then your Speedin Energy strips, and say when you use them.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('dea210991422037c', 'brand_speedin', '04417da083e43839', 'upload', 'amb/brand_speedin/inspo-infraredi-bag-two-things.mp4', 'Infraredi (inspiration)', 'Crouch next to your gym bag, sports bag or work bag and say: two things that never leave my bag. Pull out your gear, then your Speedin Energy strips, and say when you use them.', '5b0bde9e8509bdf9', 1, 1, 14);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('6bfbee530d15952b', 'brand_speedin', '65c17bef036d1527', 0, 0, 15, 'live', 'Reply to a comment: what is actually in it?', 'Answering a real question feels helpful, and people stay for the answer.', 'Anyone, no face needed', 'Sleep', 'Comment reply, hands only', '["Replying to the comment asking how a strip even works.", "You asked what is in it, so here is the back of the pack.", "Yes, it really melts. Watch."]', '[{"label": "Open · 0 to 3s", "text": "Comment bubble on screen, pack in your hands."}, {"label": "Middle", "text": "Flip to the label, point at the key ingredients, peel a strip and show how thin it is."}, {"label": "Close", "text": "Strip on your fingertip next to the pack. Say: 30 strips, one a day."}]', 'Comment bubble on screen over your hands holding the pack', 'Close up on the label with your finger on the line that matters', '[{"brand": "Shameless Snacks", "what": "Reply to a real comment (like: wait, how does a strip work?) with the comment bubble on screen. Hands only: show the pack, flip it, point at the label, peel a strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('691eb688ed6c8d60', 'brand_speedin', '6bfbee530d15952b', 'upload', 'amb/brand_speedin/inspo-shameless-comment-reply.mp4', 'Shameless Snacks (inspiration)', 'Reply to a real comment (like: wait, how does a strip work?) with the comment bubble on screen. Hands only: show the pack, flip it, point at the label, peel a strip.', '65c17bef036d1527', 1, 1, 15);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('d913894ec1f292b9', 'brand_speedin', '4dde23db55e2a5b3', 0, 0, 16, 'live', 'Nobody warned me about this', 'Nobody warned me pulls in everyone it happened to.', 'Women 30 plus, busy moms (not pregnant or nursing)', 'Hair Skin & Nails', 'Storytime talking head', '["Nobody warned me about what a stressful year does to your hair.", "I am taking care of everyone else. This is my one thing for me.", "No one tells you this part."]', '[{"label": "Open · 0 to 3s", "text": "Talking head, hand in your hair, first line."}, {"label": "Middle", "text": "Explain the busy life. Show the strip and put it on. Say it is one step, no new routine."}, {"label": "Close", "text": "Back to camera, calm. Say this is the one small thing you do for you."}]', 'You holding your hair up, frustrated face', 'Quick cut to you outside with your coffee, the strip already on', '[{"brand": "Pique", "what": "Talk to camera about the hair and skin change nobody warned you about (stress, a busy year, getting older), touch your hair, then show the one easy thing you added: a Speedin Hair Skin & Nails strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ab854c079cff94f2', 'brand_speedin', 'd913894ec1f292b9', 'upload', 'amb/brand_speedin/inspo-pique-nobody-warned.mp4', 'Pique (inspiration)', 'Talk to camera about the hair and skin change nobody warned you about (stress, a busy year, getting older), touch your hair, then show the one easy thing you added: a Speedin Hair Skin & Nails strip.', '4dde23db55e2a5b3', 1, 1, 16);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('40cf551df7422486', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 17, 'live', 'I regret buying my boyfriend this', 'A fake complaint is a fun way to say it works.', 'Creators with a partner, gift angle', 'Energy', 'Fake regret, talking head', '["I bought this for my boyfriend and honestly I regret it.", "Do not buy your husband these.", "This was supposed to be a gift. Now I have a problem."]', '[{"label": "Open · 0 to 3s", "text": "Kitchen counter, pack in hand, say the first line straight faced."}, {"label": "Middle", "text": "Explain his old routine (two coffees, cans in the truck) and that he just puts a strip on now."}, {"label": "Close", "text": "The punchline: now he is up and done before you. Hold up the pack."}]', 'You holding the pack with a serious face', 'The twist: what actually changed for your partner', '[{"brand": "Tradesman Nutrition", "what": "Stand in your kitchen with the Speedin pack and say you regret buying it for your partner, because now they are up before you every morning. Keep it playful, one take.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('b6239f1d4d1b8623', 'brand_speedin', '40cf551df7422486', 'upload', 'amb/brand_speedin/inspo-tradesman-boyfriend-regret.mp4', 'Tradesman Nutrition (inspiration)', 'Stand in your kitchen with the Speedin pack and say you regret buying it for your partner, because now they are up before you every morning. Keep it playful, one take.', '5b0bde9e8509bdf9', 1, 1, 17);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('4a0b41d20c6369f4', 'brand_speedin', '65c17bef036d1527', 0, 0, 18, 'live', 'My bag does not need to sound like a maraca', 'The rattle sound is a hook people hear before they see it.', 'Anyone, no face needed', 'Sleep', 'Hands only swap', '["My bag does not need to sound like a maraca every time I move.", "Listen to this.", "Swapping my whole pill situation for this."]', '[{"label": "Open · 0 to 3s", "text": "Shake the bag right at the mic. Text on screen."}, {"label": "Middle", "text": "Pull out each bottle and line them up. Slide the Speedin pack in."}, {"label": "Close", "text": "Shake the bag again: silence. Zip it up."}]', 'A purse being shaken, pill bottles rattling', 'Bottles come out, one flat pack goes in, bag is quiet', '[{"brand": "Emmafy", "what": "Shake your bag so we hear the pill bottles rattle, then swap them for the flat Speedin pack. Hands only, filmed in your car or at your desk.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('b694b8201a718638', 'brand_speedin', '4a0b41d20c6369f4', 'upload', 'amb/brand_speedin/inspo-emmafy-bag-rattle.mp4', 'Emmafy (inspiration)', 'Shake your bag so we hear the pill bottles rattle, then swap them for the flat Speedin pack. Hands only, filmed in your car or at your desk.', '65c17bef036d1527', 1, 1, 18);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('b97c4de2116076ad', 'brand_speedin', '4dde23db55e2a5b3', 0, 0, 19, 'live', 'Supplement hacks have gone too far', 'Making fun of the old way makes the new way obvious in 20 seconds.', 'Anyone with a funny face and a cluttered cabinet', 'Hair Skin & Nails', 'Over the top before, simple after', '["Supplement routines have gone too far.", "This is my morning. Every morning.", "Or you could just do this."]', '[{"label": "Open · 0 to 3s", "text": "Extreme close up, handful of pills, text on screen."}, {"label": "Middle", "text": "Struggle: water glass, shaker, gummy jar. Keep it quick and silly."}, {"label": "Close", "text": "Text: or just one strip. Peel, place, smile."}]', 'Your face super close, too many pills in your hand, text: this has gone too far', 'Hard cut to calm you with one strip', '[{"brand": "Hostage Tape", "what": "Close up comedy: line up every pill bottle, powder, shaker and gummy jar you own and struggle through them. Then cut to you peeling one Speedin strip and smiling.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('0c9217c66d2d4c40', 'brand_speedin', 'b97c4de2116076ad', 'upload', 'amb/brand_speedin/inspo-hostage-hacks-too-far.mp4', 'Hostage Tape (inspiration)', 'Close up comedy: line up every pill bottle, powder, shaker and gummy jar you own and struggle through them. Then cut to you peeling one Speedin strip and smiling.', '4dde23db55e2a5b3', 1, 1, 19);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('27774e2e3655343b', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 20, 'live', 'My old morning drink build vs one strip', 'Watching a long build makes one strip feel like a relief.', 'Coffee lovers, kitchen creators', 'Energy', 'Kitchen build, then the swap', '["This used to be my morning. Every step.", "First, two scoops. Then the frother. Then...", "I timed my old morning drink. Eight minutes."]', '[{"label": "Open · 0 to 3s", "text": "Wide kitchen shot, jars everywhere, first line."}, {"label": "Middle", "text": "Speed through the steps with a word on screen for each. Then stop."}, {"label": "Close", "text": "Peel a strip, put it on, grab your keys. You can still drink coffee for the taste, say the strip is your energy now."}]', 'Counter full of jars and a frother, you mid scoop', 'You stop halfway, push it all aside and pick up the strip', '[{"brand": "Everyday Dose", "what": "Film the full ritual of your old morning drink (scoops, frother, creamer, the mess), talking through every step. Then show your new morning: one Speedin Energy strip, done.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('f0f6b8fb7896dbff', 'brand_speedin', '27774e2e3655343b', 'upload', 'amb/brand_speedin/inspo-dose-coffee-build.mp4', 'Everyday Dose (inspiration)', 'Film the full ritual of your old morning drink (scoops, frother, creamer, the mess), talking through every step. Then show your new morning: one Speedin Energy strip, done.', '5b0bde9e8509bdf9', 1, 1, 20);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('8d84ecb1609f1ec3', 'brand_speedin', '65c17bef036d1527', 0, 0, 21, 'live', 'This was the topic of conversation at our family dinner', 'Hearing that your whole family asked about it is word of mouth, not an ad.', 'Adults with busy families, people who host holidays, anyone with a nosy sister', 'Sleep', 'Kitchen counter storytime, one take', '["This was the topic of conversation at our family dinner.", "My sister would not stop asking how I am sleeping lately.", "I did not expect my bedtime routine to come up at Thanksgiving."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on the counter, kitchen lights low, you already talking."}, {"label": "Middle", "text": "Tell the dinner story in your own words. Open a Speedin Sleep strip and put it on your tongue. Say it melts in about 30 seconds, no water, no pill."}, {"label": "Close", "text": "Turn off the kitchen light and head to bed. Say how you have been waking up, as how it felt for you. Sleep strips are for bedtime only, never with alcohol or before driving."}]', 'You at the counter at night, pouch in hand, mid story', '"And then my mom asked for one"', '[{"brand": "Supergut", "what": "Film at your kitchen counter at night, phone propped up, one take. Tell the story of the family get together where everyone kept asking how you are sleeping lately, then show your real wind down: Speedin Sleep strip on the tongue, no water, then lights out. Water or tea in the shot only, never wine or a drink.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('110dceff6cf09bb2', 'brand_speedin', '8d84ecb1609f1ec3', 'upload', 'amb/brand_speedin/inspo-supergut-family-asked.mp4', 'Supergut (inspiration)', 'Film at your kitchen counter at night, phone propped up, one take. Tell the story of the family get together where everyone kept asking how you are sleeping lately, then show your real wind down: Speedin Sleep strip on the tongue, no water, then lights out. Water or tea in the shot only, never wine or a drink.', '65c17bef036d1527', 1, 1, 21);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('05b3c4c6ecba5363', 'brand_speedin', '4dde23db55e2a5b3', 0, 0, 22, 'live', 'POV: your partner keeps stealing your strips', 'Someone stealing it is the most honest review there is.', 'Couples, roommates, siblings who share a bathroom', 'Hair Skin & Nails', 'Two person POV skit, caught stealing', '["POV: your partner is stealing from you.", "The best review I got was my husband taking mine.", "I bought these for me. Apparently they are ours now."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot at the mirror. Partner pulls a strip out of your pouch. Text on screen: POV your partner is stealing from you."}, {"label": "Middle", "text": "You catch them. Quick back and forth. Then you both face the camera, one puts a strip on the tongue, and you say it melts in about 30 seconds, no water."}, {"label": "Close", "text": "You take the pouch back and say what you have noticed with your hair or nails, as how it looks to you. End with a line about needing two pouches now."}]', 'Your partner sneaking a strip out of your pouch at the mirror', '"You weren''t going to tell me about these?"', '[{"brand": "Fleur", "what": "Film with your partner in the bathroom or bedroom, phone on the counter. Catch them taking your Speedin Hair Skin & Nails strips. You play annoyed, they play innocent, then you both show the pouch and say why you take it. Funny, short, real.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('866564add7d301d0', 'brand_speedin', '05b3c4c6ecba5363', 'upload', 'amb/brand_speedin/inspo-fleur-partner-steals.mp4', 'Fleur (inspiration)', 'Film with your partner in the bathroom or bedroom, phone on the counter. Catch them taking your Speedin Hair Skin & Nails strips. You play annoyed, they play innocent, then you both show the pouch and say why you take it. Funny, short, real.', '4dde23db55e2a5b3', 1, 1, 22);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f379ff177c690ddb', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 23, 'live', 'Two games before noon and I am the one who needs the snack', 'Every sports parent knows the early Saturday, so the field alone makes them stop.', 'Sports parents, coaches, anyone with early weekend games', 'Energy', 'Sports Saturday vlog, voiceover', '["Saturday called for two soccer games and a football game.", "Sports parent life means I am at the field before the sun is.", "Everyone packs snacks for the kids. Nobody packs anything for the parents."]', '[{"label": "Open · 0 to 3s", "text": "Field at sunrise or the parking lot, phone in your hand, time showing on screen."}, {"label": "Middle", "text": "Quick clips: unloading the trunk, setting up chairs, then you leaning on the car with the strip going on your tongue. Say no water, no cup to hold while you cheer."}, {"label": "Close", "text": "You on the sideline cheering. Say what the rest of your Saturday felt like. Keep the pouch in your bag, away from kids."}]', 'Wide shot of an empty field at sunrise with the time on screen', 'Close up of the trunk: chairs, cooler, blankets, and the little Speedin pouch', '[{"brand": "Guava Family", "what": "Film your real sports Saturday as a voiceover: the field at 7am, the car trunk full of chairs and coolers, the sideline. Before the first whistle, you at the car with a Speedin Energy strip. The strip is for you, the grown up. Kids can be in the background playing but never with the pouch.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('21752a719c6af8d3', 'brand_speedin', 'f379ff177c690ddb', 'upload', 'amb/brand_speedin/inspo-guava-sideline-saturday.mp4', 'Guava Family (inspiration)', 'Film your real sports Saturday as a voiceover: the field at 7am, the car trunk full of chairs and coolers, the sideline. Before the first whistle, you at the car with a Speedin Energy strip. The strip is for you, the grown up. Kids can be in the background playing but never with the pouch.', '5b0bde9e8509bdf9', 1, 1, 23);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('3eecbcab64ce1a5c', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 24, 'live', 'Come on a run with me, and the halfway strip', 'A run you can follow along with feels like hanging out, and the halfway stop shows the strip in real life.', 'Runners, walkers, anyone training for a 5K', 'Energy', 'Run with me vlog, selfie style', '["Come on a run with me. Today''s game is finding everything yellow.", "Let''s go on a run together. First, fit check.", "Halfway through every long run I do the same thing."]', '[{"label": "Open · 0 to 3s", "text": "Phone in hand at home or by the front door. Quick fit check, then slide the Speedin pouch into your running belt."}, {"label": "Middle", "text": "Selfie clips while you run, plus quick shots of the yellow things you spot. Plain text for the miles, like mile 1, mile 2. At halfway, stop, strip on your tongue, say it melts in about 30 seconds and there is no bottle to carry."}, {"label": "Close", "text": "Finish the run and say how the second half felt, in your own words. No pop-up graphics or stickers, just you and the route."}]', 'You at home doing a fit check: come on a run with me', '"Okay, halfway. Three miles down, three to go" as you pull the pouch out of your belt', '[{"brand": "Honey Stinger", "what": "Film your own run with the phone in your hand, selfie style. Pick a game for the run, like spotting everything yellow on your route. Quick fit check at home, strip pouch in your running belt, then at the halfway point stop, put a Speedin Energy strip on your tongue and keep going. No water bottle needed.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('4d8c9d99a5477f4e', 'brand_speedin', '3eecbcab64ce1a5c', 'upload', 'amb/brand_speedin/inspo-honeystinger-color-run.mp4', 'Honey Stinger (inspiration)', 'Film your own run with the phone in your hand, selfie style. Pick a game for the run, like spotting everything yellow on your route. Quick fit check at home, strip pouch in your running belt, then at the halfway point stop, put a Speedin Energy strip on your tongue and keep going. No water bottle needed.', '5b0bde9e8509bdf9', 1, 1, 24);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('df0b583b33db8412', 'brand_speedin', '5b0bde9e8509bdf9', 0, 0, 25, 'live', 'By hour eight of my shift, my water bottle is still full', 'Someone with a nonstop job saying "I don''t have time to stop and drink something" explains no water better than we can.', 'Nurses, teachers, servers, retail and warehouse workers, anyone on long shifts', 'Energy', 'Get ready for my shift vlog, talking head', '["By hour eight of my shift, my coffee is cold and my water bottle is still full.", "Twelve hour shifts will humble you.", "Nobody at my job has time to stop and drink anything."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on the counter, you already dressed for work, talking straight to camera."}, {"label": "Middle", "text": "Quick clips of getting ready and packing your work bag with the Speedin pouch. Then a selfie clip at work or on your break: strip on your tongue, melts in about 30 seconds, no water, back to it."}, {"label": "Close", "text": "Back home at the end of the shift, hold up the full water bottle and say how the day felt, in your own words. Never film patients, students or customers, and keep work badges and logos out of shot."}]', 'You in scrubs or uniform at the kitchen counter: by hour eight of my shift', 'Holding up your still-full water bottle at the end of the shift', '[{"brand": "DryWater", "what": "Film it on a real work day in your scrubs or uniform. Tell the truth about your job: you never get to stop, your coffee goes cold, your water bottle comes home full. Show getting ready, packing your work bag with the Speedin pouch, and a quick strip on the tongue in the hallway or break room. No water, no stopping. Works for nurses, teachers, servers, anyone who is on their feet all day.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('07bb1926ee92e2f4', 'brand_speedin', 'df0b583b33db8412', 'upload', 'amb/brand_speedin/inspo-drywater-nurse-shift.mp4', 'DryWater (inspiration)', 'Film it on a real work day in your scrubs or uniform. Tell the truth about your job: you never get to stop, your coffee goes cold, your water bottle comes home full. Show getting ready, packing your work bag with the Speedin pouch, and a quick strip on the tongue in the hallway or break room. No water, no stopping. Works for nurses, teachers, servers, anyone who is on their feet all day.', '5b0bde9e8509bdf9', 1, 1, 25);
